-- M5.7 — Collections phase close + E2E test fixtures.\n--\n-- Adds: collections_close function to finalize a collection phase,\n--       plus test fixtures and RLS updates for collect/waive/reschedule.\n--\n-- ---------------------------------------------------------------------------\n-- 1. Collections phases table.\n-- ---------------------------------------------------------------------------\n\ncreate table if not exists public.collections_phases (\n  id uuid primary key default gen_random_uuid(),\n  contract_id uuid not null references public.contracts (id) on delete restrict,\n  phase_number integer not null check (phase_number > 0),\n  start_date date not null default current_date,\n  end_date date,\n  status text not null default 'active'\n    check (status in ('active', 'closed', 'paused')),\n  total_collected numeric(14, 2) not null default 0 check (total_collected >= 0),\n  target_amount numeric(14, 2) not null default 0 check (target_amount >= 0),\n  closed_at timestamptz,\n  closed_by uuid references public.profiles (id),\n  created_at timestamptz not null default now(),\n  created_by uuid references public.profiles (id),\n  unique (contract_id, phase_number)\n);\n\ncreate index if not exists collections_phases_contract_idx\n  on public.collections_phases (contract_id, phase_number);\n\n-- RLS\nalter table public.collections_phases enable row level security;\ndrop policy if exists collections_phases_select_authorized on public.collections_phases;\ncreate policy collections_phases_select_authorized\non public.collections_phases\nfor select\nto authenticated\nusing (\n  public.has_permission('collections.view')\n  and exists (\n    select 1 from public.contracts as c\n    where c.id = collections_phases.contract_id\n      and public.is_branch_member(c.branch_id)\n  )\n);\nrevoke all on public.collections_phases from authenticated, anon;\ngrant select on public.collections_phases to authenticated;\n\n-- ---------------------------------------------------------------------------\n-- 2. collections_close.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.collections_close(\n  p_contract_id uuid,\n  p_close_date date default null\n)\nreturns public.collections_phases\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  contract_row public.contracts;\n  phase_row public.collections_phases;\n  v_close_date date := coalesce(p_close_date, current_date);\n  v_total_collected numeric;\nbegin\n  if not public.has_permission('contracts.view') then\n    raise exception 'forbidden' using errcode = '42501';\n  end if;\n\n  select * into contract_row\n  from public.contracts\n  where id = p_contract_id\n  for update;\n\n  if not found then\n    raise exception 'contract_missing' using errcode = 'P0001';\n  end if;\n\n  if not public.is_branch_member(contract_row.branch_id) then\n    raise exception 'forbidden' using errcode = '42501';\n  end if;\n\n  -- check contract is active or completed\n  if contract_row.status not in ('active', 'completed') then\n    raise exception 'contract_not_active' using errcode = 'P0001';\n  end if;\n\n  -- get or create phase 1\n  select * into phase_row\n  from public.collections_phases\n  where contract_id = p_contract_id and phase_number = 1;\n\n  if not found then\n    insert into public.collections_phases (\n      contract_id, phase_number, start_date, status,\n      target_amount, created_by, created_at\n    )\n    values (\n      p_contract_id, 1, current_date, 'closed',\n      coalesce(contract_row.financed_amount, 0), auth.uid(), now()\n    )\n    returning * into phase_row;\n  else\n    -- close the phase\n    if phase_row.status = 'closed' then\n      raise exception 'phase_already_closed' using errcode = 'P0001';\n    end if;\n\n    -- compute total collected from payments for this contract\n    select coalesce(sum(amount), 0) into v_total_collected\n    from public.payments\n    where contract_id = p_contract_id\n      and payment_type in ('down_payment', 'installment', 'extra')\n      and (phase_row.start_date <= current_date or phase_row.end_date is not null);\n\n    update public.collections_phases\n    set status = 'closed',\n        end_date = v_close_date,\n        total_collected = v_total_collected,\n        closed_at = now(),\n        closed_by = auth.uid()\n    where id = phase_row.id\n    returning * into phase_row;\n  end if;\n\n  return phase_row;\nend;\n$$;\n\nrevoke all on function public.collections_close(uuid, date) from public, anon;\ngrant execute on function public.collections_close(uuid, date) to authenticated, service_role;\n\n-- ---------------------------------------------------------------------------\n-- 3. Update installments status on close.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.close_contract_installments(p_contract_id uuid)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_count integer := 0;\n  v_contract public.contracts;\nbegin\n  select * into v_contract from public.contracts where id = p_contract_id;\n\n  if not found then raise exception 'contract_missing' using errcode = 'P0001'; end if;\n  if not public.is_branch_member(v_contract.branch_id) then\n    raise exception 'forbidden' using errcode = '42501';\n  end if;\n\n  -- mark all pending/partial installments as paid on close\n  update public.installments i\n  set status = 'paid', paid_at = now()\n  from public.installment_schedules s\n  where s.contract_id = p_contract_id\n    and s.status = 'active'\n    and i.schedule_id = s.id\n    and i.status in ('pending', 'partial', 'overdue')\n    and i.paid_amount < i.amount;\n\n  get diagnostics v_count = row_count;\n  return v_count;\nend;\n$$;\n\nrevoke all on function public.close_contract_installments(uuid) from public, anon;\ngrant execute on function public.close_contract_installments(uuid) to authenticated, service_role;\n",